int f(int n) {
    if (n == 0) return 0;
    return n + f(n - 1);
}

void main() {
    IO.println(f(4));
}

void count(int n) {
    if (n == 0) return;
    count(n - 1);
    IO.print(n + " ");
}

void main() {
    count(3);
}

String rev(String s) {
    if (s.isEmpty()) return "";
    return rev(s.substring(1)) + s.charAt(0);
}

void main() {
    IO.println(rev("abc"));
}

int pow2(int n) {
    return n == 0 ? 1 : 2 * pow2(n - 1);
}

void main() {
    IO.println(pow2(10));
}
